// Added during the gpt-3.5-turbo -> gpt-5.6-terra migration.
// A shut-down model fails loudly. A replacement model can fail quietly:
// empty text, cut-off JSON, a refusal, or different keys. This node turns
// those quiet failures into errors so they reach the alert branch.
const ALLOWED_CATEGORY = ['billing', 'bug', 'how_to', 'account', 'other'];
const ALLOWED_URGENCY = ['low', 'normal', 'high'];

const choice = $json;
if (choice.finish_reason === 'length') {
  throw new Error('AI step stopped at the token limit (finish_reason=length). Reasoning tokens count toward Maximum Number of Tokens; raise it.');
}
if (choice.message && choice.message.refusal) {
  throw new Error('Model refused: ' + String(choice.message.refusal).slice(0, 200));
}
let out = choice.message ? choice.message.content : undefined;
if (out === null || out === undefined || (typeof out === 'string' && out.trim() === '')) {
  throw new Error('AI output is empty (no text returned).');
}
if (typeof out === 'string') {
  try {
    out = JSON.parse(out);
  } catch (e) {
    throw new Error('AI output is not valid JSON: ' + out.slice(0, 200));
  }
}
if (!out || typeof out !== 'object' || Array.isArray(out)) {
  throw new Error('AI output is empty or not a JSON object.');
}
const problems = [];
if (!ALLOWED_CATEGORY.includes(out.category)) problems.push('category=' + JSON.stringify(out.category));
if (!ALLOWED_URGENCY.includes(out.urgency)) problems.push('urgency=' + JSON.stringify(out.urgency));
if (typeof out.summary !== 'string' || out.summary.trim() === '') problems.push('summary missing');
if (typeof out.reply_draft !== 'string' || out.reply_draft.trim() === '') problems.push('reply_draft missing');
if (problems.length > 0) {
  throw new Error('AI output failed the schema check: ' + problems.join('; '));
}
return {
  json: {
    category: out.category,
    urgency: out.urgency,
    summary: out.summary.trim(),
    reply_draft: out.reply_draft.trim()
  }
};
